newsource='''from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    edge_counts = Counter()
    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and g[r][c] != bg:
                edge_counts[g[r][c]] += 1
    if not edge_counts:
        return g
    marker = edge_counts.most_common(1)[0][0]
    seed_colors = [v for v in counts if v not in (bg, marker)]
    if not seed_colors:
        return g
    seed_color = max(seed_colors, key=lambda v: counts[v])

    # Find contiguous marker bars on each boundary.
    def edge_runs(side):
        if side == 'top': coords = [(0,c) for c in range(w)]
        elif side == 'bottom': coords = [(h-1,c) for c in range(w)]
        elif side == 'left': coords = [(r,0) for r in range(h)]
        else: coords = [(r,w-1) for r in range(h)]
        result = []
        i = 0
        while i < len(coords):
            if g[coords[i][0]][coords[i][1]] != marker:
                i += 1
                continue
            j = i
            while j+1 < len(coords) and g[coords[j+1][0]][coords[j+1][1]] == marker:
                j += 1
            result.append((i, j))
            i = j+1
        return result

    def cast(side, start, offset):
        if side == 'top': r, c, dr, dc = 0, start + offset, 1, 0
        elif side == 'bottom': r, c, dr, dc = h-1, start + offset, -1, 0
        elif side == 'left': r, c, dr, dc = start + offset, 0, 0, 1
        else: r, c, dr, dc = start + offset, w-1, 0, -1
        r += dr; c += dc
        while 0 <= r < h and 0 <= c < w:
            val = g[r][c]
            if val == marker:
                break
            if val == seed_color:
                g[r][c] = 4
                break
            if val != bg:
                break
            g[r][c] = seed_color
            r += dr; c += dc

    # Opposite bars copy the offsets of the colored points between them.
    for side_a, side_b in (('left', 'right'), ('top', 'bottom')):
        runs_a, runs_b = edge_runs(side_a), edge_runs(side_b)
        for a0, a1 in runs_a:
            for b0, b1 in runs_b:
                if a1-a0 != b1-b0:
                    continue
                length = a1-a0+1
                offsets = set()
                for r in range(h):
                    for c in range(w):
                        if g[r][c] in (bg, marker):
                            continue
                        pos = r if side_a in ('left','right') else c
                        if a0 <= pos <= a1:
                            offsets.add(pos-a0)
                        elif b0 <= pos <= b1:
                            offsets.add(pos-b0)
                for off in offsets:
                    if 0 <= off < length:
                        cast(side_a, a0, off)
                        cast(side_b, b0, off)
    return g
